changeSet.sql:
alter table iys_consent_tasks
add constraint chk_iys_retained_recipient_window
check ((retained_recipient_ciphertext is null) = (recipient_retain_until is null));
create index idx_iys_retained_recipient_expiry
on iys_consent_tasks (recipient_retain_until)
where retained_recipient_ciphertext is not null and is_deleted = false;
